{"type":"assistant","message":{"model":"claude-sonnet-4-6","id":"msg_011CdcTdeP8oSxMtMHufjcv3","type":"message","role":"assistant","content":[{"type":"tool_use","id":"toolu_01C73tE1wESurLQKGq5B9vLe","name":"Write","input":{"file_path":"[REDACTED:local-path:edaa76a09182]/mnt/outputs/artifacts/competitive-positioning-cadence/landscape_draft.json","content":"{
  "startup": {
    "name": "Cadence",
    "slug": "_startup",
    "description": "Seed-stage B2B SaaS field-service scheduling and dispatch software for US SMB service businesses"
  },
  "competitors": [
    {
      "name": "ServiceTitan",
      "slug": "servicetitan",
      "category": "direct",
      "description": "Full-suite field service management platform originally built for larger residential and commercial HVAC, plumbing, and electrical contractors. Now one of the largest FSM platforms with enterprise ambitions.",
      "key_differentiators": [
        "Comprehensive platform covering scheduling, dispatch, CRM, invoicing, payroll, and marketing",
        "Deep integrations and large partner ecosystem",
        "Strong brand among larger contractors and home services franchises"
      ],
      "why_included": "Dominant player in FSM; investors will ask about it immediately. Targets larger SMB and mid-market; relevant as the 'enterprise ceiling' Cadence must position against."
    },
    {
      "name": "Jobber",
      "slug": "jobber",
      "category": "direct",
      "description": "SMB-focused field service management software serving home service businesses (lawn care, cleaning, HVAC, plumbing). Known for strong UX, mobile app, and transparent pricing.",
      "key_differentiators": [
        "Purpose-built for SMB home service businesses with intuitive UX",
        "Strong mobile-first design for field technicians",
        "Transparent, affordable subscription pricing starting at low monthly tiers"
      ],
      "why_included": "Most direct SMB competitor to Cadence; shares the same ICP (small home service businesses). Investors will view Jobber as the clearest benchmark for Cadence."
    },
    {
      "name": "Housecall Pro",
      "slug": "housecall-pro",
      "category": "direct",
      "description": "SMB field service management app targeting small home service businesses with mobile-first dispatch, booking, and payment features. Known for ease of use and strong customer support.",
      "key_differentiators": [
        "Mobile-first interface widely adopted by sole proprietors and micro-SMBs",
        "Online booking and consumer-facing scheduling features",
        "Active user community and strong customer support reputation"
      ],
      "why_included": "Overlapping SMB ICP; competes on ease of use and affordability. Represents the lower-end of the SMB FSM market that Cadence will encounter."
    }
  ],
  "candidate_axes": [
    {
      "pair_id": "axes-a",
      "x_axis": "SMB Simplicity (setup speed & ease of use)",
      "y_axis": "Scheduling & Dispatch Intelligence (automation depth)",
      "rationale": "Captures the core trade-off in FSM for SMBs: how fast can a small shop get value vs. how smart is the dispatching logic. Cadence is hypothesized to differentiate on dispatch intelligence while remaining accessible to SMBs. ServiceTitan scores high on intelligence but low on simplicity; Jobber and Housecall Pro score high on simplicity but moderate on intelligence."
    },
    {
      "pair_id": "axes-b",
      "x_axis": "Target Customer Size (micro-SMB to mid-market)",
      "y_axis": "Platform Breadth (scheduling-focused to full ERP)",
      "rationale": "Reveals the SMB-focus vs. enterprise-bloat spectrum and the point-solution vs. all-in-one trade-off. Cadence as a scheduling/dispatch-focused tool positions as a point solution for SMBs, while ServiceTitan sits in the mid-market/full-platform quadrant. This axis pair exposes the over-engineering problem Cadence solves."
    },
    {
      "pair_id": "axes-c",
      "x_axis": "Time to First Value (days to go live)",
      "y_axis": "Scheduling Automation Depth (manual to AI-optimized dispatch)",
      "rationale": "Maps the implementation friction vs. dispatch sophistication trade-off that directly drives SMB purchase decisions. SMBs want to be live fast; intelligence is a secondary purchase driver. Cadence's claimed advantage in fast setup and smart dispatch is directly tested here."
    }
  ],
  "deck_competitors_excluded": [],
  "metadata": {
    "run_id": "20260801T175544Z"
  }
}
